mapper.select:

where w.del_flag = '0'

    and w.warehouse_name like concat('%', #{query.warehouseName}, '%')


    and w.warehouse_code like concat('%', #{query.warehouseCode}, '%')


    and w.warehouse_type = #{query.warehouseType}


    and w.supplier_id = #{query.supplierId}


    and w.status = #{query.status}


    and (w.warehouse_name like concat('%', #{query.keyword}, '%')
         or w.warehouse_code like concat('%', #{query.keyword}, '%')
         or w.location like concat('%', #{query.keyword}, '%'))

order by w.create_time desc

select count(1)
from inv_warehouse
where warehouse_code = #{warehouseCode}
  and del_flag = '0'

    and warehouse_id != #{excludeId}
